// The songs, and the notation they are written in.
//
// This game ships no audio files. Every note is generated by the browser at
// play time, which is why the whole project is still a handful of text files.
// ADR 0004 says why. `audio.js` does the playing; this file is pure and holds
// only the notes, so the parser can be tested with no sound card in sight.
//
// Notation: a channel is one string of tokens separated by spaces.
//
//   "c4:4 e4:4 g4:8 r:4"
//
// Each token is a note name, then a colon, then how many sixteenths it lasts.
// `r` is a rest. A note name is a letter a to g, an optional `#` or `b`, then
// the octave number, so `f#3` and `bb4` are both fine. On the drum channel the
// names are `k` for kick, `s` for snare and `h` for hat.
//
// The music leans on highlife and Afrobeat: a pentatonic melody over an
// off-beat bass and a busy hat, rather than the march a Game Boy usually plays.

/** Semitone offsets from C, for every letter. */
const LETTERS = { c: 0, d: 2, e: 4, f: 5, g: 7, a: 9, b: 11 };

/** The drum sounds the noise channel knows. */
export const DRUMS = ["k", "s", "h"];

/**
 * Turn a note name into a frequency in hertz.
 * @returns {number|null} null for a name that is not a note
 */
export function noteFrequency(name) {
  const match = /^([a-g])([#b]?)(-?\d)$/i.exec(String(name ?? "").trim());
  if (!match) return null;
  const [, letter, accidental, octave] = match;
  let semitone = LETTERS[letter.toLowerCase()];
  if (accidental === "#") semitone += 1;
  if (accidental === "b") semitone -= 1;
  // Middle C is c4, and midi note 60. A4 is midi 69 and 440 hertz.
  const midi = (Number(octave) + 1) * 12 + semitone;
  return 440 * 2 ** ((midi - 69) / 12);
}

/**
 * Read one token.
 * @returns {{freq: number|null, drum: string|null, sixteenths: number}|null}
 *   null when the token cannot be read at all
 */
export function parseToken(token) {
  const text = String(token ?? "").trim();
  if (!text) return null;
  const [name, length] = text.split(":");
  const sixteenths = Number(length ?? 4);
  if (!Number.isFinite(sixteenths) || sixteenths <= 0) return null;
  if (name === "r") return { freq: null, drum: null, sixteenths };
  if (DRUMS.includes(name)) return { freq: null, drum: name, sixteenths };
  const freq = noteFrequency(name);
  if (freq === null) return null;
  return { freq, drum: null, sixteenths };
}

/**
 * Read a whole channel into notes with a start time in sixteenths.
 * A token that cannot be read is skipped, so one typo costs one note.
 * @returns {Array<{freq: number|null, drum: string|null, at: number, sixteenths: number}>}
 */
export function parseChannel(text) {
  const notes = [];
  let at = 0;
  for (const token of String(text ?? "").trim().split(/\s+/)) {
    const parsed = parseToken(token);
    if (!parsed) continue;
    notes.push({ ...parsed, at });
    at += parsed.sixteenths;
  }
  return notes;
}

/** How many sixteenths a channel lasts. */
export function channelLength(text) {
  const notes = parseChannel(text);
  if (notes.length === 0) return 0;
  const last = notes[notes.length - 1];
  return last.at + last.sixteenths;
}

/** How long one sixteenth lasts in seconds, at this tempo in beats per minute. */
export function sixteenthSeconds(bpm) {
  return 60 / Math.max(1, bpm) / 4;
}

/** How long a whole song lasts in seconds. */
export function songSeconds(song) {
  return songLength(song) * sixteenthSeconds(song.bpm);
}

/** The length of the longest channel, which is how long the loop is. */
export function songLength(song) {
  const lengths = (song.channels ?? []).map((channel) => channelLength(channel.notes));
  return lengths.length === 0 ? 0 : Math.max(...lengths);
}

