/** Every song this game can play. */
export const SONG_IDS = Object.keys(SONGS);

/**
 * One song by name.
 * @returns {object|null} null when there is no song by that name
 */
export function getSong(id) {
  return SONGS[id] ?? null;
}

/**
 * The cry of one creature, worked out from its name.
 *
 * Twenty one hand-written cries would be twenty one more things to keep in
 * step with the species table. Instead the name itself picks the pitch, the
 * shape and the roughness, so every creature has its own voice, the voice never
 * changes, and a creature added later gets one for free.
 *
 * A heavy creature should sound heavy, so the caller passes its weight and a
 * low creature drops in pitch.
 *
 * @param {string} speciesId
 * @param {number} [weight] in kilograms, from the species table
 * @returns {{start:number, end:number, seconds:number, rough:number, wobble:number}}
 */
export function cryFor(speciesId, weight = 20) {
  let hash = 2166136261;
  for (const character of String(speciesId ?? "")) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  const pick = (shift, span) => ((hash >>> shift) & 0xff) / 255 * span;

  // A heavy creature growls; a light one chirps. The scale is generous because
  // the roster runs from a 0.4 kilogram fly to a 400 kilogram hippo.
  const heaviness = Math.min(1, Math.log10(Math.max(0.2, weight) + 1) / 2.7);
  const base = 520 - heaviness * 380 + pick(0, 160);
  const rise = pick(8, 1) > 0.5 ? 1 : -1;
  const end = Math.max(70, base * (1 + rise * (0.2 + pick(16, 0.45))));
  return {
    start: Math.max(70, base),
    end,
    seconds: 0.34 + pick(24, 0.22),
    rough: 0.15 + pick(4, 0.5),
    wobble: 6 + pick(12, 22),
  };
}
